  "ساعات اوج مصرف و شبکه‌های همراه اول/ایرانسل دارای اختلال شدید؛ استریم ویدیو، دانلود و ارتباط سرور به سرور (Tunnel).": "Peak consumption hours and heavily disrupted MCI/Irancell networks; video streaming, downloads, and tunnel connections.",
