  "سیستم‌های بازرسی عمیق بسته (DPI) اپراتورها در ایرانسل و همراه اول دقیقاً پکت‌های اولیه را اسکن کرده، مقدار SNI را استخراج می‌کنند و در صورت حضور در لیست سیاه، در کسری از میلی‌ثانیه با تزریق پکت‌های جعلی": "MCI and Irancell DPI systems scan initial packets, extract the SNI, and if blacklisted, terminate connections within milliseconds via forged packets",
  "سیستم‌های فیلترینگ با ارسال بسته‌های کاوشگر (Active Probes) به پورت سرور شما سعی می‌کنند متوجه شوند چه سرویسی پشت آن در حال اجراست.": "Censorship systems send active probes to your server port to determine what service is running behind it.",
  "سیستم‌های فیلترینگ هوشمند (DPI) پورت استاندارد 443 را به شدت زیر ذره‌بین قرار می‌دهند. اگر ترافیک با رفتار وبسایت تطابق نداشته باشد، پورت ممکن است پس از چند ساعت مسدود یا دچار اختلال شود.": "Smart DPI systems heavily scrutinize port 443. If traffic diverges from normal website behavior, the port may be blocked or throttled within hours.",
