  "فایروال با دیدن دامنه مجاز در SNI، فرض می‌کند کاربر در حال استفاده از یک سرویس قانونی است و بسته را عبور می‌دهد. اما این روش در گذشته با دو بن‌بست فلج‌کننده روبرو شد:": "Firewall sees allowed SNI, assumes legitimate service, and lets packet pass. However, this historically hit two crippling dead-ends:",
