  "فایروال‌های DPI ایران، گواهینامه‌های خودساخته (Self-Signed) را در جا شناسایی کرده و ارتباط را به عنوان ترافیک مشکوک قطع می‌کنند. پنل": "Iranian DPI firewalls immediately detect self-signed certificates and terminate connection as suspicious. The panel",
  "فایروال‌های پیشرفته (مانند GFW و تجهیزات سانسور ایران) پس از مشاهده ترافیک نامتعارف، بلافاصله از سرورهای کاوشگر خود یک درخواست آزمایشی به IP و پورت سرور شما می‌فرستند؛ اگر پاسخی غیر از سایت واقعی دریافت کنند، IP سرور شما را در کمتر از ۱۰ ثانیه در سطح کل کشور مسدود می‌کنند.": "Advanced firewalls (GFW and Iran DPI) immediately send active probes to your server IP/port upon detecting irregular traffic; if the response diverges from the real site, your IP is blocked nationwide within 10 seconds.",
