  "وضعیت باینری‌ها و موتورهای تانل بروزرسانی شد.": "Status of tunnel binaries and engines updated.",
  "وقتی شما با یک فیلترشکن به سایتی امن (مانند اینستاگرام یا واتساپ) متصل می‌شوید، ترافیک TLS شما داخل یک ترافیک TLS دیگر بسته‌بندی می‌شود. فایروال‌های مجهز به هوش مصنوعی با تحلیل طول بسته‌ها (Packet Length Distribution) در چند میلی‌ثانیه اول هندشیک، وجود دو لایه TLS را متوجه شده و پورت را قطع می‌کردند.": "When you connect via VPN to a secure site, your TLS traffic is wrapped inside another TLS layer. AI-equipped firewalls analyzing packet length distribution in the first few milliseconds detect double TLS and drop the connection.",
  "وقتی کاوشگر فایروال به پورت سرور شما وصل می‌شود، چون کلید احراز هویت خصوصی ندارد، سرور Sing-box هوشمندانه بسته را عیناً به سرور واقعی گوگل پاس می‌دهد و پاسخ واقعی را به فایروال برمی‌گرداند؛ فایروال پس از بررسی مطمئن می‌شود که این سرور یک سرور معتبر است و آن را مسدود نمی‌کند!": "When a firewall active probe hits your server port without private auth keys, Sing-box intelligently forwards the packet untouched to the real Google server and returns Google's genuine response; verifying this, the firewall concludes the server is legitimate and avoids blocking!",
  "ویرایش اوت‌باند": "Edit Outbound",
  "ویرایش اینباند": "Edit Inbound",
