  "پاکسازی": "Purge / Clear",
  "پایداری بالا در مواقع فیلتر بودن IP اصلی سرور.": "High stability when server primary IP is blocked.",
  "پایین": "Low",
  "پرفورمنس فوق‌العاده بالا، رله همزمان بسته‌های UDP و TCP بدون کوچک‌ترین سربار اضافی هدر وب.": "Ultra-high performance, concurrent UDP and TCP relay without any web header overhead.",
  "پروتکل CDN": "CDN Protocol",
  "پروتکل Hysteria 2 (Brutal QUIC)": "Hysteria 2 Protocol (Brutal QUIC)",
  "پروتکل NaiveProxy مستقیماً از کتابخانه شبکه رسمی مرورگر Chromium گوگل کروم استفاده می‌کند. به دلیل اینکه از متد استاندارد تونل وب HTTP/2 CONNECT بهره می‌برد، امضای ترافیک آن (JA3/JA4) تفاوتی با وب‌گردی طبیعی یک کاربر عادی ندارد.": "NaiveProxy directly utilizes the official Google Chromium browser network library. Using standard HTTP/2 CONNECT tunneling, its traffic signatures (JA3/JA4) are indistinguishable from normal user web browsing.",
  "پروتکل QUIC مجهز به الگوریتم مبهم‌سازی Salamander جهت نامرئی‌سازی هدرهای": "QUIC protocol with Salamander obfuscation algorithm to render headers invisible",
  "پروتکل QUIC مجهز به الگوریتم مبهم‌سازی Salamander جهت نامرئی‌سازی هدرهای QUIC در برابر DPI": "QUIC protocol with Salamander obfuscation to render QUIC headers invisible against DPI",
  "پروتکل ShadowTLS v3": "ShadowTLS v3 Protocol",
  "پروتکل Shadowsocks 2022": "Shadowsocks 2022 Protocol",
  "پروتکل Shadowsocks در سال ۲۰۲۲ بازطراحی کامل شد. در این ویرایش از تابع مشتق‌گیری کلید مدرن BLAKE3 و رمزنگاری‌های AEAD-GCM استفاده شده است که پروتکل را در برابر حملات بازپخش (Replay Attacks) و اسکنرهای فایروال کاملاً مصون می‌سازد.": "Shadowsocks was completely overhauled in 2022. This version uses BLAKE3 key derivation and AEAD-GCM ciphers, providing absolute immunity against replay attacks and active firewall scanners.",
  "پروتکل TLS طراحی شد تا همه چیز را رمزگذاری کند، اما در آغاز دست‌اندازی (Handshake)، کلاینت باید بگوید با کدام سایت کار دارد. این نام در فیلد": "TLS was designed to encrypt everything, but at handshake onset, the client must specify target host. This name in the field",
  "پروتکل TUIC v5 (QUIC 0-RTT)": "TUIC v5 Protocol (QUIC 0-RTT)",
  "پروتکل Trojan TLS": "Trojan TLS Protocol",
  "پروتکل UDP فوق سریع با کنترل ازدحام Brutal مناسب شبکه‌های با پکت لاس بالا": "Ultra-fast UDP protocol with Brutal congestion control suitable for high packet loss networks",
  "پروتکل VLESS Reality (XTLS-Vision)": "VLESS Reality Protocol (XTLS-Vision)",
  "پروتکل VMess WebSocket": "VMess WebSocket Protocol",
  "پروتکل VMess پروتکل پایه شرکت V2Fly با رمزنگاری پیشرفته متقارن AEAD است. بزرگترین مزیت VMess، قابلیت انتقال داده از داخل بسته‌های استریم استاندارد وب‌سوکت (WebSocket) است که به مدیر شبکه اجازه می‌دهد ترافیک را از پشت CDNهای ابری نظیر Cloudflare عبور داده و آی‌پی مسدودشده سرور را مخفی نگاه دارد.": "VMess is the foundational protocol created by V2Fly featuring advanced symmetric AEAD encryption. Its greatest advantage is transporting data inside standard WebSocket streams, allowing traffic to proxy through Cloudflare CDN and conceal blocked server IPs.",
  "پروتکل استاندارد HTTPS وب": "Standard HTTPS Web Protocol",
  "پروتکل استاندارد سازگار با کلاینت‌های قدیمی و جدید": "Standard protocol compatible with legacy and modern clients",
  "پروتکل امنیتی سنتی و آزمایش‌شده با رمزنگاری پیشرفته AEAD.": "Battle-tested traditional security protocol with advanced AEAD encryption.",
  "پروتکل تروجان با لایه انتقال مدرن gRPC بر بستر HTTP/2 جهت هندشیک سریع‌تر": "Trojan protocol with modern gRPC transport over HTTP/2 for faster handshakes",
  "پروتکل مدرن QUIC مبتنی بر Rust با حداقل تاخیر هندشیک و کنترل BBR": "Modern Rust-based QUIC protocol with minimal handshake latency and BBR control",
  "پروتکل و طراح": "Protocol & Designer",
  "پروکسی رمزنگاری‌شده AEAD مدرن با کمترین میزان مصرف باتری و منابع سرور.": "Modern AEAD encrypted proxy with minimal battery drain and server resources.",
  "پروکسی لوکال سیستم": "System Local Proxy",
  "پروکسی محلی": "Local Proxy",
  "پشتیبانی همگانی": "Universal Support",
  "پشتیبانی کامل از CDN و وب‌سوکت": "Full CDN & WebSocket Support",
  "پنهان‌سازی ترافیک پروکسی به عنوان یک وبسایت HTTPS کاملاً طبیعی با گواهی معتبر SSL.": "Disguises proxy traffic as genuine HTTPS website with valid SSL certificate.",
  "پنهان‌سازی تونل پشت سرورهای اپل یا مایکروسافت بدون نیاز به گواهی اختصاصی.": "Disguises tunnel behind Apple or Microsoft servers without requiring custom certificates.",
