  "پژوهشگران امنیت شبکه و توسعه‌دهندگان هسته Xray / Sing-box": "Network Security Researchers & Xray/Sing-box Core Developers",
  "پیاده‌سازی سبک QUIC در زبان Rust؛ ارسال داده‌های اپلیکیشن در اولین بسته بدون معطلی دست‌اندازی (0-RTT)؛ قابلیت Connection Migration برای جابجایی بین دکل‌های مخابراتی بدون قطعی کانکشن.": "Lightweight QUIC implementation in Rust; 0-RTT data transmission in first packet; Connection Migration for seamless cell tower handovers without drops.",
