  "پیش‌نمایش داده‌های اکسل و CSV:": "Excel & CSV Data Preview:",
  "پینگ بسیار پایین، روانی استثنایی در بازی‌های آنلاین و تماس‌های صوتی و تصویری بدون افت کیفیت.": "Ultra-low ping, exceptional smoothness in online gaming, voice & video calls without degradation.",
  "پینگ کمتر و مصرف پردازنده بهینه‌تر نسبت به وب‌سوکت سنتی.": "Lower ping and optimized CPU usage compared to traditional WebSocket.",
  "چرا REALITY اختراع شد؟": "Why was REALITY invented?",
  "چگونه این بحران تاریخی را برای همیشه حل کرد؟ این راهنما نقشه راه مدیر سرور برای درک این معماری است.": "How did it solve this historic crisis forever? This guide is the admin roadmap to understanding this architecture.",
  "چگونه فایروال ترافیک رمزنگاری‌شده HTTPS را فیلتر می‌کند؟ چرا جعل سنتی SNI شکست خورد و فناوری": "How does firewall filter encrypted HTTPS traffic? Why did traditional SNI spoofing fail and technology",
