  "کانفیگ کامل کلاینت Sing-box در کلیپ‌بورد کپی شد (آماده Paste در نرم‌افزار).": "Complete Sing-box client config copied to clipboard (ready to paste into app).",
  "کانفیگ کلاینت برای کپی وجود ندارد.": "No client config available to copy.",
  "کانفیگ کپی شد.": "Config copied.",
  "کانفیگ‌ها، لینک‌ها و بارکد اختصاصی کاربر": "User Dedicated Configs, Links & QR Code",
  "کاهش مصرف باتری گوشی و اتصالات همزمان امن بدون قطعی.": "Reduces phone battery drain and provides reliable concurrent connections without dropouts.",
  "کاوش فعال فایروال (Active Probing)": "Firewall Active Probing",
  "کلاینت در بسته هندشیک TLS کلید عمومی را به صورت نامتقارن (X25519) ارسال می‌کند؛ سرور در صورت تایید اتصال پروکسی را باز می‌کند و در صورت ورود پروب فایروال، بسته را عیناً به سرور Dest (گوگل یا مایکروسافت) فوروارد می‌کند.": "Client sends public key asymmetrically (X25519) in TLS handshake; server establishes proxy connection if verified, and forwards probes untouched to Dest server (Google or Microsoft).",
  "کلاینت مجاز، کد احراز هویت را در متغیرهای تصادفی هندشیک پنهان می‌کند بدون اینکه ردپایی در ترافیک باقی بماند.": "Authorized clients hide auth token within random handshake variables leaving zero trace in traffic.",
  "کلاینت‌های اندروید، ویندوز و لینوکس جهت تونل کردن کامل کل دستگاه.": "Android, Windows, and Linux clients to completely tunnel the entire device.",
  "کلودفلر / CDN": "Cloudflare / CDN",
