  "دامنه‌ای که انتخاب می‌کنید حتماً باید از پروتکل‌های وب مدرن پشتیبانی کند.": "The domain you select must support modern web protocols.",
  "دامنه‌های تست‌شده و توصیه‌شده (بدون مسدودی):": "Tested & Recommended Unblocked Domains:",
  "در استاندارد پروتکل TLS، فیلدی به نام": "In the TLS protocol standard, a field named",
  "در زمان تشدید فیلترینگ، اپراتورها پورت‌های UDP را پس از چند گیگابایت مصرف موقتاً مسدود می‌کنند. قابلیت چندپورتی (Multi-Port Hopping) در هیستریا ۲ باعث می‌شود کلاینت به طور پویا در هر ثانیه پورت خود را عوض کند تا فایروال هرگز فرصت مسدودسازی پیدا نکند.": "During intense censorship, operators temporarily block UDP ports after several gigabytes of usage. Multi-Port Hopping in Hysteria 2 dynamically switches ports every second, giving firewalls no window to block.",
  "در پروتکل‌های سنتی، تا زمان برقراری کامل هندشیک چندصد میلی‌ثانیه زمان هدر می‌رود. در TUIC کلاینت داده‌های خود را از همان پکت اول ارسال می‌کند و نیازی به انتظار برای پاسخ دست‌اندازی اولیه سرور ندارد.": "In legacy protocols, hundreds of milliseconds are lost completing handshakes. In TUIC, the client transmits payload data from the very first packet without waiting for server handshake replies.",
  "در سناریوهای فیلترینگ شدید همراه اول و ایرانسل، پورت 443 را برای این پروتکل انتخاب کنید تا ترافیک کاملاً طبیعی جلوه کند.": "Under severe MCI and Irancell filtering scenarios, select port 443 for this protocol so traffic appears completely natural.",
  "دستورالعمل انتخاب پورت مناسب:": "Port Selection Guidelines:",
  "دیوار آتش به دلیل عدم وجود کلید رمزنگاری، قادر به بازرسی هدرهای داخلی نخواهد بود.": "The firewall cannot inspect inner headers due to the absence of decryption keys.",
  "رمز عبور (Password):": "Password:",
  "رمزنگاری Salamander هدرهای کوییک را به نویزهای تصادفی و فاقد الگوی هندسی تبدیل می‌کند تا فایروال نتواند آن را به عنوان ترافیک QUIC شناسایی کند.": "Salamander encryption transforms QUIC headers into patternless random noise, preventing firewalls from recognizing QUIC traffic.",
  "طراحی مهندس ihciah (لایه نشست ShadowTLS)": "Designed by ihciah (ShadowTLS Session Layer)",
