  "مناسب برای خطوط وای‌فای ثابت بدون پکت‌لاست بالا.": "Suitable for fixed Wi-Fi lines without high packet loss.",
  "هرگز از دامنه‌های مشهور (مانند گوگل، مایکروسافت، یاهو) استفاده نکنید، زیرا فایروال با تطبیق عدم تعلق IP به آن شرکت‌ها ارتباط را قطع می‌کند. همچنین از دامنه‌های فیلترشده (مانند یوتیوب یا توییتر) نیز استفاده نکنید.": "Never use famous domains (like Google, Microsoft, Yahoo), as firewalls terminate connections upon detecting IP/ASN mismatch. Never use blocked domains (like YouTube or Twitter) either.",
  "هرگز از گوگل و دامنه‌های مشهور استفاده نکنید. بهترین گزینه‌ها CDNهای سریع با TLS 1.3 و ALPN h2 هستند:": "Never use Google or famous domains. The best options are fast CDNs with TLS 1.3 and ALPN h2:",
  "هنگامی که پروب‌های فیلترینگ پورت شما را بررسی می‌کنند، چون کلید احراز هویت ندارند، سرور بسته را فوراً به سرور اصلی فوروارد می‌کند؛ اسکنر فایروال نیز پاسخ ۱۰۰٪ رسمی دریافت کرده و این سرور را یک سرور عادی وب می‌داند.": "When active censorship probes inspect your port, lacking authentication keys, the server immediately forwards the packet to the real server; the firewall scanner receives 100% authentic responses and considers it a normal web server.",
  "هیستریا ۲ پاسخی قاطع به اختلالات عمدی و پکت‌لاست‌های تحمیلی زیرساخت است. در شرایطی که تمام پروتکل‌های مبتنی بر TCP با افت شدید سرعت مواجه می‌شوند، هیستریا ۲ سرعت خط را به حداکثر ممکن می‌رساند.": "Hysteria 2 is the definitive answer to deliberate network throttling and imposed packet loss. While all TCP protocols suffer severe drops, Hysteria 2 pushes line speed to its absolute maximum.",
  "و شاهکار": "and the masterpiece",
  "پروتکل ShadowTLS ابداع مهندس ihciah برای مقابله با بازرسی عمیق بسته‌ها (DPI) و خنثی کردن اسکن‌های فعال است بدون اینکه نیازی به راه‌اندازی سرورهای سنگین وبسایت باشد.": "ShadowTLS was invented by ihciah to counter DPI and neutralize active probes without the burden of hosting heavy websites.",
  "پروتکل TUIC با حذف کامل لایه‌های اضافه، مستقیم‌ترین ارتباط ممکن بین کلاینت و سرور را برقرار می‌کند. کمترین پینگ، حذف تاخیر اولیه و حفظ اتصال هنگام تغییر اینترنت، برگ برنده این پروتکل است.": "TUIC establishes the most direct client-server connection by stripping unnecessary overhead. Minimal ping, zero initial delay, and connection persistence across network handovers are its key triumphs.",
  "پروتکل استاندارد QUIC دارای هدرهای مشخصی است که فایروال‌های DPI آن را شناسایی و مسدود می‌کنند.": "Standard QUIC protocol has recognizable headers that DPI firewalls identify and block.",
